/**
 * The employee guide. Plain language, one topic per thing you actually do,
 * each with a picture of the real screen.
 *
 * Screenshots live in /public/guide and are regenerated by
 * `node scripts/capture-guide.mjs` against a running dev server, so they never
 * drift from what the app looks like.
 */

export type GuideTopic = {
  id: string;
  title: string;
  /** One line: why you would open this screen. */
  summary: string;
  /** Admin-only topics are hidden from technicians. */
  admin?: boolean;
  /** Where in the app this topic lives, if it is a screen you can open. */
  href?: string;
  /** What to do, in order. */
  steps: string[];
  /** The thing people get wrong, or the thing worth knowing. */
  note?: string;
  shot?: { src: string; alt: string };
};

export type GuideSection = {
  id: string;
  title: string;
  blurb: string;
  topics: GuideTopic[];
};

