/**
 * Fills in the bits of the guide that come from settings, so the text can never
 * claim hours the shop does not actually keep.
 */
export function fillTokens(text: string, values: { workHours: string }): string {
  return text.replace(/\{workHours\}/g, values.workHours);
}

export function guideFor(role: string): GuideSection[] {
  if (role === "admin") return GUIDE;
  return GUIDE.map((s) => ({ ...s, topics: s.topics.filter((t) => !t.admin) })).filter((s) => s.topics.length > 0);
}
